create or replace function t002_working_days(
  p_start in date,
  p_end   in date
) return pls_integer is
  -- Working days (Monday to Friday) between p_start and p_end, counting both dates.
  l_day   date        := trunc(p_start);
  l_count pls_integer := 0;
begin
  if p_start is null or p_end is null or trunc(p_end) < trunc(p_start) then
    return 0;
  end if;
  while l_day <= trunc(p_end) loop
    -- Check if the day is a weekday (Monday=2 to Friday=6 in standard SQL DATE dayofweek, or using ISO week day)
    -- TRUNC(date, 'IW') returns the Monday of the week. If the difference is 0, it's Monday. If 4, it's Friday.
    -- A simpler check for Mon-Fri is to check the day of the week (1=Sunday, 7=Saturday in Oracle default NLS settings, or 1=Monday to 7=Sunday if using ISO).
    -- Using TO_CHAR(l_day, 'D') or checking against the day of the week relative to Monday.
    -- For ISO week day (1=Mon, 7=Sun):
    if to_char(l_day, 'D') in ('1', '2', '3', '4', '5') then
      l_count := l_count + 1;
    end if;
    l_day := l_day + 1;
  end loop;
  return l_count;
end t002_working_days;
/

create or replace function t002_working_days(
  p_start in date,
  p_end   in date
) return pls_integer is
  -- Working days (Monday to Friday) between p_start and p_end, counting both dates.
  l_day   date        := trunc(p_start);
  l_count pls_integer := 0;
begin
  if p_start is null or p_end is null or trunc(p_end) < trunc(p_start) then
    return 0;
  end if;
  while l_day <= trunc(p_end) loop
    -- Check if the day is a weekday (Monday=1 to Friday=5 in ISO week day format, which Oracle supports via TRUNC(date, 'IW'))
    -- TRUNC(date, 'IW') returns the Monday of the week. If the difference between l_day and the start of its week is 0, it's Monday.
    -- If the difference is 4, it's Friday. If it's 5 or 6, it's Saturday or Sunday.
    if l_day - trunc(l_day, 'IW') < 5 then
      l_count := l_count + 1;
    end if;
    l_day := l_day + 1;
  end loop;
  return l_count;
end t002_working_days;
/
